"use client";

// THE TAKE GRIDS (STEPS-DESIGN §2: ads frames "image take grid (1-9 adopt, N next)", ads motion
// "clip list + adopt"; v1 ads/AdsFrames.tsx, ads/AdsMotion.tsx). RAIL: the picked scenario's
// shots, adopted or not. PRIMARY: the selected shot's takes - three across, six for 9:16. Takes
// are generated by an act behind its receipt (v1 showed no cost for image takes at all); adopting
// is an op. A grid made for another scenario than the one picked now is not drawn as this one's.
import { useState } from "react";

import type { AdsClips, AdsTakes, PartView } from "@gt/domain/partView";
import { Button } from "@gt/ui/components/button/Button.tsx";
import { Chip } from "@gt/ui/components/chip/Chip.tsx";
import { Empty } from "@gt/ui/components/empty/Empty.tsx";
import { ErrorLine } from "@gt/ui/components/errorline/ErrorLine.tsx";
import { PartWorkspace } from "@gt/ui/components/part/PartWorkspace.tsx";
import { RailList } from "@gt/ui/components/part/RailList.tsx";
import { secs, walk } from "@gt/ui/components/part/part.ts";
import { Tally } from "@gt/ui/components/tally/Tally.tsx";
import { useKeys } from "@gt/ui/keymap/dispatch";
import { cx } from "@gt/ui/components/cx.ts";

import type { EditorProps } from "./PartEditor.tsx";
import s from "./Frames.module.css";

type ShotLike = { readonly id: string; readonly durationS: number; readonly adopted: string | null };

function ShotRow({ x, n, noun }: { readonly x: ShotLike; readonly n: number; readonly noun: "take" | "clip" }) {
  return (
    <div className={s.row} data-shot={x.id}>
      <span className={s.tc}>{secs(x.durationS)}</span>
      <span className={s.kind}>{x.id}</span>
      <span className={s.title}>{n === 0 ? "—" : `${n} ${noun}${n === 1 ? "" : "s"}`}</span>
      <span className={s.marks}>
        <span className={cx(s.m, x.adopted !== null ? s.ready : s.owed)} aria-label={x.adopted !== null ? "adopted" : "not adopted"}>
          {x.adopted !== null ? "■" : "□"}
        </span>
      </span>
    </div>
  );
}

function useShotWalk<T extends ShotLike>(shots: readonly T[]) {
  const [chosen, setChosen] = useState<string | null | undefined>(undefined);
  const sel = chosen === undefined ? (shots[0]?.id ?? null) : chosen;
  return {
    sel,
    shot: shots.find((x) => x.id === sel),
    setSel: setChosen,
    next: (dir: 1 | -1) =>
      walk(
        shots.map((x) => x.id),
        sel,
        dir,
      ),
  };
}

export function AdsTakesEditor({ frame, send, busy, error, act, data: d }: EditorProps<PartView<"frames">> & { readonly data: AdsTakes }) {
  const w = useShotWalk(d.shots);
  const shot = w.shot;
  const adopted = d.shots.filter((x) => x.adopted !== null).length;
  // One fact list for the dispatcher and the legend: the legend drew "takes" for a shot with none.
  const facts = [...(shot === undefined ? [] : ["unit"]), ...((shot?.takes.length ?? 0) > 0 ? ["takes"] : [])];
  useKeys(
    "part.frames",
    {
      item: ({ index }) => {
        const next = w.next(index === 0 ? 1 : -1);
        if (next === null) return false;
        w.setSel(next);
      },
      "next-missing": () => {
        const next = d.shots.find((x) => x.adopted === null && x.id !== w.sel) ?? d.shots.find((x) => x.adopted === null);
        if (next === undefined) return false;
        w.setSel(next.id);
      },
      render: () => (shot === undefined ? false : act("image-takes", `takes ${shot.id}`, shot.id)),
      adopt: ({ index }) => {
        const take = shot?.takes[index];
        if (shot === undefined || take === undefined || busy) return false;
        send({ op: "adopt-image", shotId: shot.id, takeId: take.id });
      },
    },
    { facts },
  );
  return (
    <PartWorkspace
      {...frame}
      mode="part.frames"
      facts={facts}
      rail={{
        label: "shots",
        children: (
          <>
            <div className={s.railHead}>
              <h3 className={s.h}>shots</h3>
              <Tally value={adopted} of={d.shots.length} label="adopted" />
            </div>
            <RailList label="shots" items={d.shots} idOf={(x) => x.id} selected={w.sel} onSelect={w.setSel} row={(x) => <ShotRow x={x} n={x.takes.length} noun="take" />} />
          </>
        ),
      }}
      primary={{
        label: "takes",
        children: (
          <div className={s.stage}>
            {error !== null && <ErrorLine message={error} live />}
            <div className={s.bar}>
              <span className={s.cell}>
                adopted <Tally value={adopted} of={d.shots.length} />
              </span>
              <Chip label="aspect" value={d.aspect} casing="lower" />
              {d.scenario !== null && <Chip label="scenario" value={d.scenario.title} casing="lower" />}
              {d.scenarioMoved && <Chip label="other scenario" tone="amber" casing="lower" />}
            </div>
            {d.scenario === null ? (
              <Empty label="no scenario picked" />
            ) : shot === undefined ? (
              <Empty label="no shot selected" />
            ) : shot.takes.length === 0 ? (
              <Empty label="no takes" action={{ label: "3 takes", size: "sm", tone: "cyan", onPress: () => act("image-takes", `takes ${shot.id}`, shot.id) }} />
            ) : (
              <div className={cx(s.grid, d.aspect === "9:16" && s.tall)} role="listbox" aria-label={`takes for ${shot.id}`}>
                {shot.takes.map((t, i) => (
                  <button
                    key={t.id}
                    type="button"
                    role="option"
                    aria-selected={t.adopted}
                    className={s.take}
                   
                    onClick={() => send({ op: "adopt-image", shotId: shot.id, takeId: t.id })}
                    data-take={t.id}
                  >
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    {t.url === null ? <span className={s.blank} /> : <img src={t.url} alt="" />}
                    <span className={s.takeFoot}>
                      <span className={s.key}>{i < 9 ? i + 1 : ""}</span>
                      {t.adopted && <Chip label="adopted" tone="emerald" casing="lower" />}
                      {t.dry && <span className={s.key}>dry</span>}
                    </span>
                  </button>
                ))}
              </div>
            )}
          </div>
        ),
      }}
      inspector={{
        label: "shot",
        children:
          shot === undefined ? (
            <Empty label="no shot selected" />
          ) : (
            <div data-region="inspector">
              <div className={s.sect}>
                <h3 className={s.h}>{shot.id}</h3>
                <p className={s.work}>{shot.brief}</p>
                {shot.super !== null && <Chip label="super" value={shot.super} casing="lower" />}
                <Chip label="duration" value={secs(shot.durationS)} casing="lower" />
              </div>
              <Button
                label={shot.takes.length === 0 ? "3 takes" : "3 more takes"}
                size="sm"
                tone="cyan"
                shortcut={{ mode: "part.frames", verb: "render" }}
                onPress={() => act("image-takes", `takes ${shot.id}`, shot.id)}
              />
            </div>
          ),
      }}
    />
  );
}

export function AdsClipsEditor({ frame, send, busy, error, act, data: d }: EditorProps<PartView<"motion">> & { readonly data: AdsClips }) {
  const w = useShotWalk(d.shots);
  const shot = w.shot;
  const adopted = d.shots.filter((x) => x.adopted !== null).length;
  // One fact list for the dispatcher and the legend: the legend drew "moving" and "clips" for a
  // shot with no still to animate and no clip to adopt.
  const facts = [...(shot?.still != null ? ["moving"] : []), ...((shot?.clips.length ?? 0) > 0 ? ["clips"] : [])];
  useKeys(
    "part.motion",
    {
      item: ({ index }) => {
        const next = w.next(index === 0 ? 1 : -1);
        if (next === null) return false;
        w.setSel(next);
      },
      render: () => (shot === undefined || shot.still === null ? false : act("render-clip", `clip ${shot.id}`, shot.id)),
      adopt: ({ index }) => {
        const c = shot?.clips[index];
        if (shot === undefined || c === undefined || busy) return false;
        send({ op: "adopt-clip", shotId: shot.id, clipId: c.id });
      },
    },
    { facts },
  );
  return (
    <PartWorkspace
      {...frame}
      mode="part.motion"
      facts={facts}
      rail={{
        label: "shots",
        children: (
          <>
            <div className={s.railHead}>
              <h3 className={s.h}>shots</h3>
              <Tally value={adopted} of={d.shots.length} label="clips" />
            </div>
            <RailList label="shots" items={d.shots} idOf={(x) => x.id} selected={w.sel} onSelect={w.setSel} row={(x) => <ShotRow x={x} n={x.clips.length} noun="clip" />} />
          </>
        ),
      }}
      primary={{
        label: "clips",
        children: (
          <div className={s.stage}>
            {error !== null && <ErrorLine message={error} live />}
            {d.scenarioMoved && <Chip label="other scenario" tone="amber" casing="lower" />}
            {d.scenario === null ? (
              <Empty label="no scenario picked" />
            ) : shot === undefined ? (
              <Empty label="no shot selected" />
            ) : (
              <>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                {shot.still === null ? <Empty label="no adopted still" /> : <img className={s.clip} src={shot.still} alt={`still for ${shot.id}`} />}
                <div className={s.grid} role="listbox" aria-label={`clips for ${shot.id}`}>
                  {shot.clips.map((c, i) => (
                    <button
                      key={c.id}
                      type="button"
                      role="option"
                      aria-selected={c.adopted}
                      className={s.take}
                     
                      onClick={() => send({ op: "adopt-clip", shotId: shot.id, clipId: c.id })}
                      data-clip={c.id}
                    >
                      {c.url === null ? <span className={s.blank} /> : <video src={c.url} muted loop autoPlay playsInline aria-label={c.id} />}
                      <span className={s.takeFoot}>
                        <span className={s.key}>{i < 9 ? i + 1 : ""}</span>
                        <span>{c.status}</span>
                        {c.adopted && <Chip label="adopted" tone="emerald" casing="lower" />}
                      </span>
                    </button>
                  ))}
                </div>
              </>
            )}
          </div>
        ),
      }}
      inspector={{
        label: "shot",
        children:
          shot === undefined ? (
            <Empty label="no shot selected" />
          ) : (
            <div data-region="inspector">
              <div className={s.sect}>
                <h3 className={s.h}>{shot.id}</h3>
                <p className={s.work}>{shot.motion}</p>
                <Chip label="duration" value={secs(shot.durationS)} casing="lower" />
              </div>
              {shot.still !== null && <Button label="animate" size="sm" tone="cyan" shortcut={{ mode: "part.motion", verb: "render" }} onPress={() => act("render-clip", `clip ${shot.id}`, shot.id)} />}
            </div>
          ),
      }}
    />
  );
}
